/* 这里放置的CSS将应用于所有皮肤 */
:root {
--theme-custom-background-image: url(https://huiji-public.huijistatic.com/gtnh/uploads/5/51/Gtnh_bg_0.png);
}
html {
scroll-padding-top: 88px;
}
#wiki-body,
#wiki-body * {
scrollbar-width: thin !important;
scrollbar-color: #bcc6d1 #edf2f7 !important;
}
#wiki-body::-webkit-scrollbar,
#wiki-body *::-webkit-scrollbar {
width: 10px;
height: 10px;
}
#wiki-body::-webkit-scrollbar-track,
#wiki-body *::-webkit-scrollbar-track {
background: #edf2f7;
border-radius: 6px;
}
#wiki-body::-webkit-scrollbar-thumb,
#wiki-body *::-webkit-scrollbar-thumb {
background: #bcc6d1;
border-radius: 6px;
border: 2px solid #edf2f7;
}
#wiki-body::-webkit-scrollbar-thumb:hover,
#wiki-body *::-webkit-scrollbar-thumb:hover {
background: #98a6b5;
}
/* Minecraftia字体，以Minecraftia和思源宋体为主，同时包括了新元素（来自cfpa.org）。 */
@font-face {
font-family: Minecraftia;
src: url("https://fs.huijiwiki.com/www/resources/font/SourceHanSerifCN-Regular.otf");
}
@font-face {
font-family: Minecraftia;
src: url("https://huiji-public.huijistatic.com/gtnh/uploads/9/90/Minecraftia.ttf");
}
@font-face {
font-family: Minecraftia;
src: url("https://huiji-public.huijistatic.com/gtnh/uploads/3/30/TartaricAcidElement.ttf");
}
@font-face {
font-family: Minecraftia;
src: url("data:font/woff2;base64,") format('woff2');
}
/* background */
#wiki-outer-body.huiji-css-hook {
/* background-image: var(--theme-custom-background-image); */
background-position: 50%;
background-size: cover;
background-repeat: no-repeat;
background-attachment: fixed;
}
#wiki-outer-body {
background: transparent;
}
#wiki-body {
position: relative;
}
#wiki-body::before {
content: "";
position: absolute;
top: -6px;
left: -6px;
width: calc(100% + 12px);
height: calc(100% + 12px);
border: solid;
border-width: 6px 8px 8px 6px;
border-image: url(https://huiji-public.huijistatic.com/gtnh/uploads/7/76/Wiki_boader.png)
6 8 8 6 round;
pointer-events: none;
}
body.random-background-applied::before {
background-color: var(--bg);
background-position: 50%;
}
.random-background-applied #wiki-body {
background-color: var(--bg-inner);
}
/* 周期表 */
.Yuansuzhouqibiao_alkali {
/* 碱金属 */
background-color: #ff6666;
}
.Yuansuzhouqibiao_alkali_earth {
/* 碱土金属 */
