/* MC风表格主体背景格式 */
.minecraftGUI {
padding-inline: 30px;
padding-block: 30px;
border-collapse: separate;
border-spacing: 0;
background-color: #C6C6C6; /* 经典的面板底色 */
/* 圆角与细黑外边框 */
border-radius: 4px;
border: 1px solid rgba(0, 0, 0, 0.4);
/* 整体右下角微弱阴影 */
box-shadow: 6px 6px 15px rgba(0, 0, 0, 0.15);
padding: 6px; /* 内部留白，增加窗口感 */
overflow: hidden;
font-family: "Minecraftia", "Microsoft YaHei", monospace;
}
.minecraftGUI td,
.minecraftGUI th {
padding: 2px;
box-sizing: border-box;
text-align: center;
vertical-align: middle;
}
/* MC风表格单元格格式 */
.minecraftGUI td {
background-color: #8B8B8B;
background-image:
linear-gradient(to right, #373737 calc(100% - 2px), transparent 2px),
linear-gradient(to bottom, #373737 calc(100% - 2px), transparent 2px),
linear-gradient(to right, transparent 2px, #FFFFFF 2px),
linear-gradient(to bottom, transparent 2px, #FFFFFF 2px);
background-repeat: no-repeat;
background-size: 100% 2px, 2px 100%, 100% 2px, 2px 100%;
background-position: 0 0, 0 0, 0 100%, 100% 0;
}
/* MC风表格标题行格式 */
.minecraftGUI th {
text-align: center;
vertical-align: middle;
border: none;
padding: 0;
width: auto;
height: auto;
background-color: rgb(200, 200, 200);
white-space: nowarp;
font-size: auto;
}
/* MC风表格单元格图片居中 */
.minecraftGUI td > img {
vertical-align: middle;
}
/* MC风表格表头格式 */
.minecraftGUI caption {
padding-bottom: 6px;
color: rgb(64, 64, 64);
text-align: center;
font-size: 24px;
font-family: minecraftia;
}
/* MC风表格自定义文字格式 */
.minecraftGUI .minecraftGUIStr,
.minecraftGUI .minecraftGUIStr td,
.minecraftGUIStr td:first-child {
background-color: rgb(200, 200, 200);
border: none;
text-align: center;
}
