}
];
var requestedModules = {};
function toElements(content) {
if (content && content.jquery) return content.toArray();
if (!content) return [document];
if (content.nodeType) return [content];
if (typeof content.length === 'number') return Array.prototype.slice.call(content);
return [document];
}
function matchesSelector(element, selector) {
var matches = element.matches || element.msMatchesSelector || element.webkitMatchesSelector;
return !!(matches && matches.call(element, selector));
}
function elementHasSelector(element, selector) {
if (!element) return false;
if (element.nodeType !== 9 && matchesSelector(element, selector)) return true;
return !!(element.querySelector && element.querySelector(selector));
}
function contentHasSelector(content, spec) {
var elements = toElements(content);
return spec.selectors.some(function (selector) {
return elements.some(function (element) {
return elementHasSelector(element, selector);
});
});
}
function loadOnDemandGadget(spec, content) {
if (requestedModules[spec.module]) return;
requestedModules[spec.module] = true;
mw.loader.using([spec.module]).then(function () {
if (spec.refireContentHook) {
mw.hook('wikipage.content').fire($(content || document));
}
}, function (error) {
requestedModules[spec.module] = false;
console.error('[OnDemandGadget] 加载失败:', spec.name, spec.module, error);
});
}
function scanOnDemandGadgets(content) {
onDemandGadgets.forEach(function (spec) {
if (contentHasSelector(content, spec)) {
loadOnDemandGadget(spec, content);
}
});
}
if (window.mw && mw.hook && mw.loader) {
mw.hook('wikipage.content').add(scanOnDemandGadgets);
if (document.readyState === 'loading') {
document.addEventListener('DOMContentLoaded', function () {
scanOnDemandGadgets(document);
});
} else {
scanOnDemandGadgets(document);
}
}
