(function () {
var prefix = mw.config.get('wgHuijiPrefix');
// 核心加载函数
// 支持三种模式，由容器的 data 属性决定：
// data-page — 直接解析已有页面，走 MediaWiki 页面缓存
// data-template — 拼成 {{模板|args}} 发 CDN smaxage 缓存请求（ApiCache 模式）
// data-wikitext / data-template+data-params — 走 mw.Api wikitext 模式（无 CDN 缓存）
function loadWikitext($container, callback) {
if ($container.hasClass('is-loaded') || $container.hasClass('is-loading')) {
return $container.data('apicache-promise') || $.Deferred().resolve().promise();
}
$container.addClass('is-loading');
var pageName = $container.data('page');
var templateName = $container.data('template');
var args = $container.data('args') || ''; // ApiCache 模式参数
var params = $container.data('params') || ''; // 旧式参数
var cacheTime = parseInt($container.data('cache-time')) || 3600;
var deferred = $.Deferred();
$container.data('apicache-promise', deferred.promise());
function onDone(html) {
var $parsed = $('<div>').html(html);
var $target = $parsed.find('#api-target');
var finalContent = $target.length > 0 ? $target.html() : html;
$container.html(finalContent).addClass('is-loaded').removeClass('is-loading');
$container.trigger('apicache:done');
mw.hook('wikipage.content').fire($container);
if (typeof callback === 'function') callback(finalContent);
deferred.resolve($container);
}
function onFail(code, result) {
$container.removeClass('is-loading');
$container.trigger('apicache:error');
console.error('MediaWiki API error:', code, result);
deferred.reject($container);
}
// 模式2 核心：通过 CDN smaxage 缓存加载一段 wikitext（必须是纯模板调用）
function loadViaCDN(wikitext, titleHint) {
var url = encodeURI(
'https://cdn.huijiwiki.com/' + prefix +
'/api.php?format=json&action=parse&disablelimitreport=true&prop=text' +
'&title=' + (titleHint || 'Main_Page') +
'&smaxage=' + cacheTime +
'&maxage=' + cacheTime +
'&text=' + wikitext
);
$.ajax({ url: url, method: 'GET' }).done(function (result, _status, xhr) {
var age = xhr.getResponseHeader('Age');
var xcache = xhr.getResponseHeader('X-Cache');
if (age !== null && parseInt(age) > 0) {
console.log('[ApiCache] CDN HIT (Age: ' + age + 's)', wikitext);
} else if (xcache) {
console.log('[ApiCache] ' + xcache, wikitext);
} else {
console.log('[ApiCache] CDN MISS (first load)', wikitext);
}
if (result && result.parse && result.parse.text) onDone(result.parse.text['*']);
}).fail(function () { onFail('ajax-fail', {}); });
}
if (pageName) {
// 模式1：页面缓存
console.log('[ApiCache] Loading via Page Cache:', pageName);
new mw.Api().get({
action: 'parse', prop: 'text',
disablelimitreport: 1,
smaxage: cacheTime, maxage: cacheTime,
page: pageName
}).done(function (data) {
if (data && data.parse && data.parse.text) onDone(data.parse.text['*']);
}).fail(onFail);
} else if (templateName && $container.data('args') !== undefined) {
// 模式2a：data-template + data-args
var wikitext = '{{' + templateName + (args ? '|' + args : '') + '}}';
loadViaCDN(wikitext, templateName);
} else {
// 模式3：旧式 wikitext / data-template+data-params
var wikitext = $container.data('wikitext')
'{{' + templateName + '|' + params.replace(/&/g, '|') + '}}';
// 如果 wikitext 本身就是一个模板调用，升级走 CDN 缓存
if (/^\s*\{\{.+\}\}\s*$/.test(wikitext)) {
var titleHint = wikitext.match(/^\s*\{\{([^|}\s]+)/);
loadViaCDN(wikitext, titleHint ? titleHint[1] : 'Main_Page');
} else {
console.log('[ApiCache] Loading via wikitext (no CDN cache):', wikitext);
new mw.Api().get({
action: 'parse', prop: 'text',
disablelimitreport: 1,
text: wikitext, contentmodel: 'wikitext'
}).done(function (data) {
if (data && data.parse && data.parse.text) onDone(data.parse.text['*']);
}).fail(onFail);
}
}
return deferred.promise();
}
// 懒加载 observer（共用一个实例）
var lazyObserver = null;
function getLazyObserver() {
if (lazyObserver) return lazyObserver;
if (!window.IntersectionObserver) return null;
lazyObserver = new IntersectionObserver(function (entries) {
entries.forEach(function (entry) {
if (entry.isIntersecting) {
var $el = $(entry.target);
lazyObserver.unobserve(entry.target);
loadWikitext($el);
}
});
}, { root: null, rootMargin: '200px', threshold: 0.1 });
return lazyObserver;
}
// 扫描并初始化内容区域内的异步容器
function processAsyncContent($content) {
// 1. async-load-container：支持 passive（立即）和 lazy（入视口）两种模式
$content.find('.async-load-container').not('.is-loaded').each(function () {
var $container = $(this);
var mode = $container.data('load-mode') || 'lazy';
if (mode === 'lazy') {
var obs = getLazyObserver();
if (obs) {
obs.observe(this);
} else {
loadWikitext($container);
}
} else {
loadWikitext($container);
}
});
// 2. async-minecraft-tt（保持原有逻辑不变）
$content.find('.async-minecraft-tt').not('.is-loaded').each(function () {
var $container = $(this);
$container.addClass('is-loaded');
var data = $container.data();
var args = [];
for (var key in data) {
if (typeof data[key] !== 'string' && typeof data[key] !== 'number') continue;
var val = decodeURIComponent(data[key] || '');
if (val !== '') {
val = val.replace(/\|/g, '{{!}}');
args.push(key + '=' + val);
}
}
new mw.Api().get({
action: 'parse',
text: '{{#invoke:Grid/Item|renderTooltipFromJS|' + args.join('|') + '}}',
contentmodel: 'wikitext',
disablelimitreport: true,
prop: 'text'
}).done(function (res) {
var html = res.parse.text['*'];
$container.html($(html).html() || html);
mw.hook('wikipage.content').fire($container);
});
});
// 3. async-echarts — 动态渲染 ECharts 图表
$content.find('.async-echarts').not('.is-loaded').each(function () {
var $container = $(this);
$container.addClass('is-loaded');
var config;
try {
config = JSON.parse($container.text().trim());
} catch (e) {
$container.html('<span style="color:red;">ECharts JSON 解析错误: ' + e.message + '</span>');
return;
}
if (!config.option) {
$container.html('<span style="color:red;">ECharts 配置缺少 option 字段</span>');
return;
}
const script = document.createElement('script');
script.src = "https://cdn.jsdelivr.net/npm/echarts@5.5.1/dist/echarts.min.js";
// 关键：备份当前全局可能存在的 echarts (哪怕是 undefined)
const __BACKUP_ECHARTS__ = window.echarts;
script.onload = function() {
// 2. 捕获刚刚加载进来的 ECharts 实例到局部变量
const localEcharts = window.echarts;
// 3. 立即还原全局变量，就像它从来没被加载过一样
window.echarts = __BACKUP_ECHARTS__;
// 4. 使用局部变量进行初始化
if (localEcharts) {
