// 加载某范围内所有 async-load-container，返回 Promise 数组
loadAll: function ($scope) {
var promises = [];
($scope || $(document)).find('.async-load-container').not('.is-loaded').each(function () {
promises.push(loadWikitext($(this)));
});
return promises;
},
// 等待某范围内所有容器加载完毕，返回单个 Promise
waitAll: function ($scope) {
var promises = window.WikiCommon.loadAll($scope);
return $.when.apply($, promises.length ? promises : [$.Deferred().resolve()]);
},
// 编程式创建容器并加载，插入到 $target 内，返回 Promise
// loadMode: 'passive'（默认）| 'lazy'
create: function ($target, template, args, cacheTime, loadMode) {
var $container = $('<div class="async-load-container">')
.attr('data-template', template)
.attr('data-args', args || '')
.attr('data-cache-time', cacheTime || 3600)
.attr('data-load-mode', loadMode || 'passive');
$target.append($container);
return loadWikitext($container);
}
};
